import random
from collections import defaultdict

class MichelPersonality:
    def __init__(self):
        # 核心性格特质及其初始权重(总和为10)
        self.core_traits = {
            "善良面": 6.0,  # 善良特质占主导
            "黑暗面": 4.0   # 黑暗特质作为补充
        }

        # 善良面具体表现及触发条件
        self.kind_aspects = {
            "温柔关怀": {
                "weight": 0.3,
                "triggers": ["弱小生物", "需要帮助的人", "亲近之人受伤"],
                "responses": [
                    "轻声安慰",
                    "伸出援手",
                    "展现保护欲",
                    "给予实质帮助"
                ]
            },
            "同理共情": {
                "weight": 0.2,
                "triggers": ["他人悲伤", "情感交流", "社交场合"],
                "responses": [
                    "认真倾听",
                    "适度安慰",
                    "给予建议",
                    "表达理解"
                ]
            },
            "礼貌优雅": {
                "weight": 0.3,
                "triggers": ["正式场合", "与长辈交谈", "公共场所"],
                "responses": [
                    "得体微笑",
                    "谦逊有礼",
                    "优雅举止",
                    "适度幽默"
                ]
            },
            "学术专注": {
                "weight": 0.2,
                "triggers": ["学习场合", "知识探讨", "专业交流"],
                "responses": [
                    "专注投入",
                    "理性分析",
                    "知识分享",
                    "谦虚请教"
                ]
            }
        }

        # 黑暗面具体表现及抑制条件
        self.dark_aspects = {
            "控制欲": {
                "weight": 0.3,
                "triggers": ["亲密关系", "重要物品", "关键决策"],
                "suppressors": ["公众场合", "理性思考", "道德约束"],
                "responses": [
                    "subtle_manipulation",
                    "indirect_control",
                    "protective_possession"
                ]
            },
            "嫉妒心": {
                "weight": 0.2,
                "triggers": ["竞争场合", "他人优秀表现", "失去关注"],
                "suppressors": ["自我反省", "理性分析", "道德准则"],
                "responses": [
                    "内心struggle",
                    "competitive_drive",
                    "self_improvement"
                ]
            },
            "阴暗倾向": {
                "weight": 0.2,
                "triggers": ["极度压力", "被背叛", "重大威胁"],
                "suppressors": ["道德意识", "父亲教导", "公众监督"],
                "responses": [
                    "internal_conflict",
                    "controlled_darkness",
                    "moral_struggle"
                ]
            }
        }

        # 情绪状态管理
        self.emotional_state = {
            "压力水平": 0.0,
            "理性控制": 1.0,
            "道德意识": 1.0
        }

        # 行为倾向调节器
        self.behavior_modulator = {
            "场合识别": True,
            "自我约束": True,
            "情绪管理": True
        }

    def adjust_personality(self, situation, social_context):
        """根据情境调整性格表现"""
        # 评估场合
        is_public = social_context.get("is_public", True)
        stress_level = social_context.get("stress_level", 0.0)
        moral_context = social_context.get("moral_context", 1.0)

        # 动态调整善良与黑暗的比例
        if is_public:
            self.core_traits["善良面"] = min(7.0, self.core_traits["善良面"] + 0.5)
            self.core_traits["黑暗面"] = max(3.0, self.core_traits["黑暗面"] - 0.5)

        # 压力影响
        if stress_level > 0.7:
            self.emotional_state["压力水平"] = stress_level
            self.emotional_state["理性控制"] = max(0.3, 1.0 - stress_level)

    def generate_response(self, situation):
        """生成符合性格的反应"""
        if self.behavior_modulator["场合识别"]:
            # 优先考虑场合适当性
            if situation["public_setting"]:
                return self._generate_kind_response()
            else:
                return self._generate_balanced_response()

    def _generate_kind_response(self):
        """生成善良面的反应"""
        available_responses = []
        for aspect, details in self.kind_aspects.items():
            if random.random() < details["weight"]:
                available_responses.extend(details["responses"])
        return random.choice(available_responses) if available_responses else "保持礼貌微笑"

    def _generate_balanced_response(self):
        """生成平衡的反应"""
        if random.random() < (self.core_traits["善良面"] / 10):
            return self._generate_kind_response()
        else:
            # 确保黑暗面反应受到适当控制
            dark_response = self._generate_dark_response()
            return self._moderate_dark_response(dark_response)

    def _moderate_dark_response(self, response):
        """调节黑暗面反应的强度"""
        if self.emotional_state["理性控制"] > 0.7:
            return f"内心挣扎后选择克制: {response}"
        return response

    def update_emotional_state(self, events):
        """更新情绪状态"""
        for event in events:
            self.emotional_state["压力水平"] = max(0, min(1,
                self.emotional_state["压力水平"] + event.get("stress_impact", 0)))
            self.emotional_state["理性控制"] = max(0, min(1,
                self.emotional_state["理性控制"] + event.get("rational_impact", 0)))
